// Validate and transform the incoming payload from CS Pulse
const body = $input.first().json.body || $input.first().json;

// Expected payload structure from CS Pulse:
// {
//   action_id: string,
//   playbook_id: string,
//   customer_id: number,
//   customer_name: string,
//   action_type: 'send_slack_alert',
//   parameters: {
//     channel: string,
//     severity: 'critical' | 'warning' | 'info',
//     title: string,
//     message: string,
//     health_score: number,
//     kpi_details: object[],
//     dashboard_url: string
//   },
//   callback_url: string,
//   triggered_by: string,
//   triggered_at: string
// }

const required = ['action_id', 'playbook_id', 'customer_id', 'parameters'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

const params = body.parameters || {};
const severity = (params.severity || 'info').toLowerCase();

// Map severity to Slack emoji and color
const severityMap = {
  critical: { emoji: ':red_circle:', color: '#FF0000' },
  warning: { emoji: ':large_orange_circle:', color: '#FFA500' },
  info: { emoji: ':large_blue_circle:', color: '#0066FF' }
};

const sev = severityMap[severity] || severityMap.info;

// Build KPI details section if provided
let kpiSection = '';
if (params.kpi_details && params.kpi_details.length > 0) {
  kpiSection = params.kpi_details.map(kpi => 
    `  *${kpi.name}*: ${kpi.value}${kpi.unit ? ' ' + kpi.unit : ''} (${kpi.trend || 'stable'})`
  ).join('\n');
}

const dashboardUrl = params.dashboard_url || 
  `${process.env.CS_PULSE_URL || '{{CS_PULSE_URL}}'}/dashboard/customer/${body.customer_id}`;

return [{
  json: {
    action_id: body.action_id,
    playbook_id: body.playbook_id,
    customer_id: body.customer_id,
    customer_name: body.customer_name || `Customer ${body.customer_id}`,
    callback_url: body.callback_url || `${process.env.CS_PULSE_URL || '{{CS_PULSE_URL}}'}/api/webhooks/playbook-callback`,
    channel: params.channel || process.env.SLACK_CHANNEL || '{{SLACK_CHANNEL}}',
    severity: severity,
    emoji: sev.emoji,
    color: sev.color,
    title: params.title || `CS Pulse Alert: ${body.customer_name || body.customer_id}`,
    message: params.message || 'A playbook action has been triggered.',
    health_score: params.health_score,
    kpi_section: kpiSection,
    dashboard_url: dashboardUrl,
    triggered_by: body.triggered_by || 'system',
    triggered_at: body.triggered_at || new Date().toISOString()
  }
}];

// Prepare success callback
const slackResponse = $input.first().json;
const originalData = $('Validate and Format').first().json;

return [{
  json: {
    action_id: originalData.action_id,
    playbook_id: originalData.playbook_id,
    customer_id: originalData.customer_id,
    status: 'completed',
    result: {
      slack_channel: originalData.channel,
      slack_message_ts: slackResponse.ts || slackResponse.message?.ts,
      slack_thread_ts: slackResponse.message?.thread_ts || null,
      message_sent: true
    },
    completed_at: new Date().toISOString()
  }
}];

// Prepare error callback
const error = $input.first();
const originalData = $('Validate and Format').first().json;

return [{
  json: {
    action_id: originalData.action_id,
    playbook_id: originalData.playbook_id,
    customer_id: originalData.customer_id,
    status: 'failed',
    error: {
      message: error.json?.message || 'Failed to send Slack message',
      code: error.json?.statusCode || 'SLACK_SEND_FAILED',
      channel: originalData.channel,
      details: error.json?.description || null
    },
    failed_at: new Date().toISOString()
  }
}];
